def run(make):
    best=None
    for b in np.linspace(0.02,1.5,149):
        S=make(b)
        cols=[t**i*P**j for i in range(3) for j in range(4)]+[S*P**j for j in range(4)]+[S*t*P**j for j in range(3)]
        e,c=nm(cols)
        if best is None or e<best[0]: best=(e,b,c)
    return best
def nm(cols):
    A=np.column_stack(cols)
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    r=dP_dt-A@c
    return np.mean(r**2)/np.var(dP_dt),c
